:root {
  --ink: #1c2b1e;
  --parchment: #e8dfc0;
  --parchment-dark: #d4c899;
  --sea-deep: #2e6e8e;
  --sea-shallow: #7ab8cc;
  --reef: #c47c3a;
  --land: #a3b87a;
  --accent-red: #8b2020;
  --accent-gold: #b8892a;
  --safe-green: #3a6e3a;
  --warn-amber: #9a6010;
  --danger-red: #8b2020;
  --border-dark: #6b5a32;
  --text-muted: #5a4e32;
}

.chart-panel {
  width: 480px;
  background: var(--parchment);
  border: 3px double var(--border-dark);
  border-radius: 4px;
  padding: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.chart-header {
  background: var(--ink);
  padding: 10px 16px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  border-bottom: 3px solid var(--accent-gold);
}

.chart-badge {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--accent-gold);
  text-transform: uppercase;
}

.chart-title {
  font-size: 20px;
  font-weight: 800;
  color: var(--parchment);
  margin: 0;
  letter-spacing: 1px;
  text-transform: uppercase;
}

.chart-subtitle {
  font-size: 11px;
  font-weight: 400;
  color: var(--parchment-dark);
  margin: 0;
  letter-spacing: 1.5px;
  text-transform: uppercase;
}

.chart-body {
  padding: 12px 14px;
  flex: 1;
}

.chart-grid {
  display: grid;
  grid-template-columns: 90px 1fr 120px;
  gap: 12px;
  align-items: start;
}

.compass-rose {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  margin: 0;
}

.rose-outer {
  width: 72px;
  height: 72px;
  border: 2px solid var(--border-dark);
  border-radius: 50%;
  background: var(--parchment-dark);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.rose-point {
  position: absolute;
  font-size: 11px;
  font-weight: 800;
  color: var(--ink);
  line-height: 1;
}

.rose-n { top: 4px; left: 50%; transform: translateX(-50%); color: var(--accent-red); }
.rose-s { bottom: 4px; left: 50%; transform: translateX(-50%); }
.rose-e { right: 6px; top: 50%; transform: translateY(-50%); }
.rose-w { left: 6px; top: 50%; transform: translateY(-50%); }

.rose-center {
  width: 10px;
  height: 10px;
  background: var(--accent-gold);
  border-radius: 50%;
  border: 2px solid var(--ink);
}

.rose-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: var(--text-muted);
  text-align: center;
  text-transform: uppercase;
  margin: 0;
}

.panel-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--text-muted);
  margin: 0 0 6px 0;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--border-dark);
}

.soundings-panel {
  border-left: 1px solid var(--border-dark);
  border-right: 1px solid var(--border-dark);
  padding: 0 12px;
}

.soundings-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.sounding-row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
}

.sounding-loc {
  flex: 1;
  font-weight: 600;
  color: var(--ink);
}

.sounding-depth {
  font-size: 11px;
  font-weight: 700;
  color: var(--sea-deep);
  font-variant-numeric: tabular-nums;
  min-width: 40px;
  text-align: right;
}

.sounding-tag {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 1px;
  text-transform: uppercase;
  padding: 1px 5px;
  border-radius: 2px;
}

.sounding-tag.safe {
  background: var(--safe-green);
  color: var(--parchment);
}

.sounding-tag.warn {
  background: var(--warn-amber);
  color: var(--parchment);
}

.sounding-tag.danger {
  background: var(--danger-red);
  color: var(--parchment);
}

.legend-panel {}

.legend-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 500;
  color: var(--ink);
}

.legend-swatch {
  width: 14px;
  height: 10px;
  border-radius: 2px;
  border: 1px solid var(--border-dark);
  flex-shrink: 0;
}

.swatch-deep { background: var(--sea-deep); }
.swatch-shallow { background: var(--sea-shallow); }
.swatch-reef { background: var(--reef); }
.swatch-land { background: var(--land); }

.chart-footer {
  background: var(--ink);
  border-top: 2px solid var(--accent-gold);
  padding: 7px 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 4px;
}

.footer-item {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: var(--parchment-dark);
  text-transform: uppercase;
}

.footer-divider {
  color: var(--accent-gold);
  font-size: 11px;
  font-weight: 700;
}
